1	package govflow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// corruptBallotsState 构造一份含投票提案 gip-bal 的合法状态文件，
13	// 再按 mutate 改写该提案的 ballots 字段，返回改写前后的字节与路径。
14	// phase 决定提案停留在哪个生命周期：
15	//   - "voting"：alice 已投赞成（300 权重，100 时刻），尚未计票；
16	//   - "passed"：alice 与 bob 均投赞成（合计 500）后已计票通过；
17	//   - "rejected"：无人投票直接计票，零参与权重拒绝；
18	//   - "executed"：通过提案已执行（资金库向 audits 转账 100）。
19	func corruptBallotsState(t *testing.T, phase string, mutate func(p map[string]any)) (path string, good, bad []byte) {
20		t.Helper()
21		dir := t.TempDir()
22		path = filepath.Join(dir, "treasury.json")
23		store, err := InitTreasury(path, 1000)
24		if err != nil {
25			t.Fatal(err)
26		}
27		in := &CreateVoteInput{
28			ID: "gip-bal",
29			Members: []VoteMember{
30				{ID: "alice", Weight: 300},
31				{ID: "bob", Weight: 200},
32			},
33			Quorum:      250,
34			StartAt:     0,
35			Deadline:    200,
36			TimelockEnd: 300,
37			Actions:     []string{"transfer:audits:100"},
38		}
39		mustCreateVote(t, store, in)
40		switch phase {
41		case "voting":
42			if _, err := store.CastVote("gip-bal", "alice", true, 100); err != nil {
43				t.Fatal(err)
44			}
45		case "passed":
46			if _, err := store.CastVote("gip-bal", "alice", true, 100); err != nil {
47				t.Fatal(err)
48			}
49			if _, err := store.CastVote("gip-bal", "bob", true, 100); err != nil {
50				t.Fatal(err)
51			}
52			if r, err := store.TallyVote("gip-bal", 200); err != nil || !r.Passed {
53				t.Fatalf("tally passed: %+v err=%v", r, err)
54			}
55		case "rejected":
56			if r, err := store.TallyVote("gip-bal", 200); err != nil || r.Passed {
57				t.Fatalf("tally rejected: %+v err=%v", r, err)
58			}
59		case "executed":
60			if _, err := store.CastVote("gip-bal", "alice", true, 100); err != nil {
61				t.Fatal(err)
62			}
63			if _, err := store.CastVote("gip-bal", "bob", true, 100); err != nil {
64				t.Fatal(err)
65			}
66			if _, err := store.TallyVote("gip-bal", 200); err != nil {
67				t.Fatal(err)
68			}
69			if _, err := store.Execute("gip-bal", 300); err != nil {
70				t.Fatal(err)
71			}
72		default:
73			t.Fatalf("unknown phase %q", phase)
74		}
75		store.Close()
76	
77		good, err = os.ReadFile(path)
78		if err != nil {
79			t.Fatal(err)
80		}
81		var clone map[string]any
82		if err := json.Unmarshal(good, &clone); err != nil {
83			t.Fatal(err)
84		}
85		p := clone["vote_proposals"].(map[string]any)["gip-bal"].(map[string]any)
86		mutate(p)
87		bad, err = json.MarshalIndent(clone, "", "  ")
88		if err != nil {
89			t.Fatal(err)
90		}
91		bad = append(bad, '\n')
92		if err := os.WriteFile(path, bad, 0o600); err != nil {
93			t.Fatal(err)
94		}
95		return path, good, bad
96	}
