98	// TestCorruptBallotsRejectedAsCorrupt：ballots 缺失、为 null 或写成
99	// 对象/字符串/数字/布尔/元素类型不对的数组，都必须判整份状态文件损坏，
100	// 且原因指出提案编号与 ballots，并区分缺失、空值与类型不符。
101	// 尚在投票、已通过、被拒绝（零参与权重）与已执行的提案适用同一条要求：
102	// 不能因为计票汇总恰好为零或资金余额仍能与执行凭据对应，就把缺损列表
103	// 补成空数组。
104	func TestCorruptBallotsRejectedAsCorrupt(t *testing.T) {
105		mutations := map[string]struct {
106			mutate func(p map[string]any)
107			want   string
108		}{
109			"missing": {
110				mutate: func(p map[string]any) { delete(p, "ballots") },
111				want:   `field "ballots" is missing`,
112			},
113			"null": {
114				mutate: func(p map[string]any) { p["ballots"] = nil },
115				want:   `field "ballots" is null`,
116			},
117			"object": {
118				mutate: func(p map[string]any) { p["ballots"] = map[string]any{"alice": "for"} },
119				want:   `field "ballots" has wrong type: want array, got object`,
120			},
121			"string": {
122				mutate: func(p map[string]any) { p["ballots"] = "alice:for" },
123				want:   `field "ballots" has wrong type: want array, got string`,
124			},
125			"number": {
126				mutate: func(p map[string]any) { p["ballots"] = 7 },
127				want:   `field "ballots" has wrong type: want array, got number`,
128			},
129			"boolean": {
130				mutate: func(p map[string]any) { p["ballots"] = true },
131				want:   `field "ballots" has wrong type: want array, got boolean`,
132			},
133			"wrong element": {
134				mutate: func(p map[string]any) { p["ballots"] = []any{5} },
135				want:   `field "ballots" has wrong type`,
136			},
137		}
138		for _, phase := range []string{"voting", "passed", "rejected", "executed"} {
139			for name, tc := range mutations {
140				t.Run(phase+"/"+name, func(t *testing.T) {
141					path, _, bad := corruptBallotsState(t, phase, tc.mutate)
142					s, err := Open(path)
143					if !errors.Is(err, ErrStateCorrupt) {
144						if s != nil {
145							s.Close()
146						}
147						t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
148					}
149					if s != nil {
150						t.Fatal("corrupt open must not return a usable store")
151					}
152					if err == nil || !strings.Contains(err.Error(), `voting proposal "gip-bal"`) {
153						t.Fatalf("error must name proposal gip-bal, got: %v", err)
154					}
155					if err == nil || !strings.Contains(err.Error(), tc.want) {
156						t.Fatalf("error must distinguish %s (%q), got: %v", name, tc.want, err)
157					}
158					// 失败的打开不得改写原文件。
159					if got, rerr := os.ReadFile(path); rerr != nil || string(got) != string(bad) {
160						t.Fatalf("failed open rewrote or normalized the state file")
161					}
162				})
163			}
164		}
165	}
