1	// Command govflow is the DAO 治理提案与执行平台 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"errors"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11		"sort"
12		"strconv"
13		"strings"
14	
15		"github.com/gzhysuiioo/govflow-proposals/govflow"
16	)
17	
18	const versionText = "govflow 0.2.0"
19	
20	func main() {
21		command := "demo"
22		if len(os.Args) > 1 {
23			command = os.Args[1]
24		}
25		args := os.Args[2:]
26		switch command {
27		case "demo":
28			runDemo()
29		case "version":
30			fmt.Println(versionText)
31		case "help", "-h", "--help":
32			usage()
33		case "init":
34			runInit(args)
35		case "register":
36			runRegister(args)
37		case "create-vote":
38			runCreateVote(args)
39		case "vote":
40			runVote(args)
41		case "tally":
42			runTally(args)
43		case "execute":
44			runExecute(args)
45		case "balances":
46			runBalances(args)
47		case "proposal":
48			runProposal(args)
49		case "proposals":
50			runProposals(args)
51		case "receipt":
52			runReceipt(args)
53		case "receipts":
54			runReceipts(args)
55		default:
56			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
57			usage()
58			os.Exit(2)
59		}
60	}
61	
62	func usage() {
63		fmt.Println(`usage: govflow <command> [flags]
64	
65	legacy commands:
66	  demo                         run the built-in voting demo
67	  version                      print the version
68	
69	local treasury commands:
70	  init       --state FILE --balance N
71	             create a new state file with the initial treasury balance
72	  register   --state FILE --id ID --timelock N --action A [--action A ...]
73	             register a passed proposal (idempotent; conflicting content errors)
74	  create-vote --state FILE --id ID --member ID:W [--member ID:W ...]
75	             [--delegate FROM:TO ...] --quorum N --start N --deadline N
76	             --timelock N [--action A ...]
77	             create a voting proposal with roster, weights, delegations and a
78	             voting window (idempotent on identical content; conflict otherwise)
79	  vote       --state FILE --id ID --voter M --choice for|against --now N
80	             cast one ballot as a final representative (repeat same choice is
81	             idempotent; changing choice errors)
82	  tally      --state FILE --id ID --now N
83	             tally a proposal at/after its deadline; repeat calls return the
84	             first result
85	  execute    --state FILE --id ID --now N
86	             execute a passed proposal whose timelock has elapsed
87	             (works for both registered and voted proposals)
88	  balances   --state FILE [--account ACCT]
89	             show treasury and recipient account balances
90	  proposal   --state FILE --id ID
91	             show one registered proposal
92	  proposals  --state FILE
93	             list all registered proposals by id
94	  receipt    --state FILE --id ID
95	             show the execution receipt of one proposal
96	  receipts   --state FILE
97	             list all receipts in the order they were successfully committed
98	
99	all treasury commands accept --json for machine-readable output.`)
100	}
101	
102	// fail prints a domain error to stderr and exits 1; usage errors exit 2.
103	func fail(err error) {
104		fmt.Fprintf(os.Stderr, "error: %v\n", err)
105		os.Exit(1)
106	}
107	
108	type commonFlags struct {
109		state  string
110		asJSON bool
111		fs     *flag.FlagSet
112	}
113	
114	func newCmdFlags(name string) *commonFlags {
115		fs := flag.NewFlagSet(name, flag.ContinueOnError)
116		fs.SetOutput(io.Discard)
117		cf := &commonFlags{fs: fs}
118		fs.StringVar(&cf.state, "state", "", "path to the local treasury state file")
119		fs.BoolVar(&cf.asJSON, "json", false, "emit machine-readable JSON")
120		return cf
121	}
122	
123	func (c *commonFlags) parse(args []string) {
124		if err := c.fs.Parse(args); err != nil {
125			fmt.Fprintf(os.Stderr, "usage error: %v\n", err)
126			c.fs.SetOutput(os.Stderr)
127			c.fs.Usage()
128			os.Exit(2)
129		}
130		if c.state == "" {
131			fmt.Fprintf(os.Stderr, "usage error: --state is required\n")
132			os.Exit(2)
133		}
134	}
135	
136	func emitJSON(v any) {
137		raw, err := json.MarshalIndent(v, "", "  ")
138		if err != nil {
139			fail(err)
140		}
141		fmt.Println(string(raw))
142	}
143	
144	func parseIntFlag(fs *flag.FlagSet, name, raw string) int64 {
145		if raw == "" {
146			fmt.Fprintf(os.Stderr, "usage error: --%s is required\n", name)
147			os.Exit(2)
148		}
149		value, err := strconv.ParseInt(raw, 10, 64)
150		if err != nil {
151			fmt.Fprintf(os.Stderr, "usage error: --%s must be an int64: %v\n", name, err)
152			os.Exit(2)
153		}
154		return value
155	}
156	
157	// actionList 收集重复出现的 --action 参数，保持登记顺序。
158	type actionList []string
159	
160	func (a *actionList) String() string { return fmt.Sprint([]string(*a)) }
161	func (a *actionList) Set(v string) error {
162		*a = append(*a, v)
163		return nil
164	}
165	
166	func runInit(args []string) {
167		cf := newCmdFlags("init")
168		balanceRaw := cf.fs.String("balance", "", "initial treasury balance (non-negative int64)")
169		cf.parse(args)
170		balance := parseIntFlag(cf.fs, "balance", *balanceRaw)
171	
172		store, err := govflow.InitTreasury(cf.state, balance)
173		if err != nil {
174			fail(err)
175		}
176		defer store.Close()
177		if cf.asJSON {
178			emitJSON(map[string]any{"state": cf.state, "treasury": balance, "initialized": true})
179			return
180		}
181		fmt.Printf("initialized %s with treasury balance %d\n", cf.state, balance)
182	}
183	
184	func runRegister(args []string) {
185		cf := newCmdFlags("register")
186		id := cf.fs.String("id", "", "proposal id (non-empty)")
187		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64)")
188		var actions actionList
189		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
190		cf.parse(args)
191		if *id == "" {
192			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
193			os.Exit(2)
194		}
195		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
196	
197		store, err := govflow.Open(cf.state)
198		if err != nil {
199			fail(err)
200		}
201		defer store.Close()
202		// 响应字段一律取这次登记实际认可的记录：首次登记为 passed；相同内容重试
203		// 保留已有记录的实际状态（passed 或 executed），已执行的提案不得报成 passed。
204		record, existed, err := store.RegisterProposal(*id, timelock, []string(actions))
205		if err != nil {
206			fail(err)
207		}
208		if cf.asJSON {
209			emitJSON(map[string]any{"id": record.ID, "state": record.State, "timelock_end": record.TimelockEnd,
210				"actions": record.Actions, "already_registered": existed})
211			return
212		}
213		if existed {
214			fmt.Printf("proposal %s already registered with identical content (state=%s)\n", record.ID, record.State)
215		} else {
216			fmt.Printf("registered passed proposal %s (%d action(s), timelock_end=%d)\n", record.ID, len(record.Actions), record.TimelockEnd)
217		}
218	}
219	
220	// memberList 收集重复的 --member ID:WEIGHT 参数，保持提交顺序。
221	type memberList []govflow.VoteMember
222	
223	func (m *memberList) String() string { return fmt.Sprint([]govflow.VoteMember(*m)) }
224	func (m *memberList) Set(v string) error {
225		id, weight, err := splitMember(v)
226		if err != nil {
227			return err
228		}
229		*m = append(*m, govflow.VoteMember{ID: id, Weight: weight})
230		return nil
231	}
232	
233	func splitMember(raw string) (string, int64, error) {
234		idx := strings.LastIndex(raw, ":")
235		if idx <= 0 || idx == len(raw)-1 {
236			return "", 0, fmt.Errorf("malformed member %q, expected ID:WEIGHT", raw)
237		}
238		id := raw[:idx]
239		weight, err := strconv.ParseInt(raw[idx+1:], 10, 64)
240		if err != nil {
241			return "", 0, fmt.Errorf("malformed member %q: weight must be int64: %v", raw, err)
242		}
243		return id, weight, nil
244	}
245	
246	// delegationList 收集重复的 --delegate FROM:TO 参数原文，保持提交顺序。
247	// 成员编号本身可含冒号（如 team:alice），FROM 与 TO 两端都可能含冒号，
248	// 因此不能在解析单个参数时切分：必须等完整成员名单齐备后，
249	// 由 resolveDelegations 结合名单确定唯一的切分点。
250	type delegationList []string
251	
252	func (d *delegationList) String() string { return fmt.Sprint([]string(*d)) }
253	func (d *delegationList) Set(v string) error {
254		*d = append(*d, v)
255		return nil
256	}
257	
258	// delegationUsageError 是 --delegate 的参数错误（格式错误或切分有歧义），
259	// 以退出码 2 结束；格式正确但无法匹配名单的错误不属于此类，按域错误退出码 1 处理。
260	type delegationUsageError struct{ reason string }
261	
262	func (e *delegationUsageError) Error() string { return e.reason }
263	
264	// resolveDelegations 结合本次提交的完整成员名单理解每条 FROM:TO 委托原文。
265	// 成员编号保持原文并区分大小写；编号可含冒号，且冒号可以出现在编号开头、
266	// 末尾或连续出现（如 ":alice"、"a:"、"a::b"），所以一条委托原文在每个冒号
267	// 位置都有一种候选切分，切分点两侧的编号仍须各自非空。
268	//
269	// 判定只依据“两端非空”这一纯语法条件与成员名单，不拿自委托/重复/循环等
270	// 业务规则替用户筛选候选：
271	//   - 原文不含冒号，或每个冒号位置的切分都会让某一端为空（如 ":alice"、
272	//     "alice:"、":"、"::"：冒号只出现在首尾、中间再无切分点）：格式错误，
273	//     参数错误（退出码 2）；
274	//   - 存在两端非空的切分，但没有任何一对都在名单里：域错误（退出码 1）；
275	//   - 两对或更多成员同时命中（即使其中某种解释随后会触发自委托、重复或循环）：
276	//     委托有歧义，参数错误（退出码 2），错误列出有歧义的原文与全部成员对；
277	//   - 恰好一对命中：按该对成员创建委托。
278	//
279	// 成员与委托参数在命令行上的排列先后不影响结果：解析前名单已收集完毕。
280	func resolveDelegations(members []govflow.VoteMember, raws []string) ([]govflow.Delegation, error) {
281		roster := make(map[string]bool, len(members))
282		for _, m := range members {
283			roster[m.ID] = true
284		}
285		out := make([]govflow.Delegation, 0, len(raws))
286		for _, raw := range raws {
287			var matches []govflow.Delegation
288			hasNonEmptySplit := false
289			for i := 0; i < len(raw); i++ {
290				if raw[i] != ':' {
291					continue
292				}
293				from, to := raw[:i], raw[i+1:]
294				// 纯语法候选：切分点两侧都非空才算“存在 FROM:TO 写法”。
295				// 编号本身允许以冒号开头、结尾或包含连续冒号，因此位于位置 0
296				// 的冒号产生的空 from、以及结尾冒号产生的空 to 都只是不合法的
297				// 切分点之一，绝不据此提前拒绝整条原文——其他冒号位置仍可能合法。
298				if from == "" || to == "" {
299					continue
300				}
301				hasNonEmptySplit = true
302				if roster[from] && roster[to] {
303					matches = append(matches, govflow.Delegation{From: from, To: to})
304				}
305			}
306			if !hasNonEmptySplit {
307				return nil, &delegationUsageError{fmt.Sprintf("malformed delegation %q, expected FROM:TO with non-empty member ids on both sides", raw)}
308			}
309			switch len(matches) {
310			case 0:
311				return nil, fmt.Errorf("delegation %q does not match any pair of members on the roster", raw)
312			case 1:
313				out = append(out, matches[0])
314			default:
315				pairs := make([]string, len(matches))
316				for i, m := range matches {
317					pairs[i] = fmt.Sprintf("%q delegating to %q", m.From, m.To)
318				}
319				return nil, &delegationUsageError{fmt.Sprintf("ambiguous delegation %q: could mean %s",
320					raw, strings.Join(pairs, " or "))}
321			}
322		}
323		return out, nil
324	}
325	
326	func runCreateVote(args []string) {
327		cf := newCmdFlags("create-vote")
328		id := cf.fs.String("id", "", "proposal id (non-empty)")
329		var members memberList
330		cf.fs.Var(&members, "member", "member ID:WEIGHT with positive int64 weight (repeatable, order irrelevant to equality)")
331		var delegationRaws delegationList
332		cf.fs.Var(&delegationRaws, "delegate", "delegation FROM:TO (repeatable, order irrelevant to equality; either side may itself contain colons and is matched against the full member roster)")
333		quorumRaw := cf.fs.String("quorum", "", "required turnout weight between 1 and total member weight")
334		startRaw := cf.fs.String("start", "", "voting start timestamp (int64, >= 0)")
335		deadlineRaw := cf.fs.String("deadline", "", "voting deadline timestamp (int64, > start)")
336		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64, >= deadline)")
337		var actions actionList
338		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
339		cf.parse(args)
340		if *id == "" {
341			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
342			os.Exit(2)
343		}
344		quorum := parseIntFlag(cf.fs, "quorum", *quorumRaw)
345		start := parseIntFlag(cf.fs, "start", *startRaw)
346		deadline := parseIntFlag(cf.fs, "deadline", *deadlineRaw)
347		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
348		if len(members) == 0 {
349			fmt.Fprintf(os.Stderr, "usage error: at least one --member ID:WEIGHT is required\n")
350			os.Exit(2)
351		}
352		// 委托切分依赖完整成员名单，必须在打开状态文件之前完成：
353		// 格式错误与歧义是参数错误（退出码 2），无法匹配名单是域错误（退出码 1），
354		// 两种失败都不触碰已有状态文件。
355		delegations, derr := resolveDelegations([]govflow.VoteMember(members), []string(delegationRaws))
356		if derr != nil {
357			var usageErr *delegationUsageError
358			if errors.As(derr, &usageErr) {
359				fmt.Fprintf(os.Stderr, "usage error: %v\n", derr)
360				os.Exit(2)
361			}
362			fail(derr)
363		}
364	
365		store, err := govflow.Open(cf.state)
366		if err != nil {
367			fail(err)
368		}
369		defer store.Close()
370		in := &govflow.CreateVoteInput{
371			ID:          *id,
372			Members:     []govflow.VoteMember(members),
373			Delegations: delegations,
374			Quorum:      quorum,
375			StartAt:     start,
376			Deadline:    deadline,
377			TimelockEnd: timelock,
378			Actions:     []string(actions),
379		}
380		view, existed, err := store.CreateVoteProposal(in)
381		if err != nil {
382			fail(err)
383		}
384		if cf.asJSON {
385			emitJSON(map[string]any{"proposal": view, "already_exists": existed})
386			return
387		}
388		if existed {
389			fmt.Printf("voting proposal %s already exists with identical content (state=%s)\n", view.ID, view.State)
390		} else {
391			fmt.Printf("created voting proposal %s: %d member(s), total_weight=%d, quorum=%d, voting=[%d,%d), timelock_end=%d, %d action(s)\n",
392				view.ID, len(view.Members), view.TotalWeight, view.Quorum, view.StartAt, view.Deadline, view.TimelockEnd, len(view.Actions))
393		}
394	}
395	
396	func runVote(args []string) {
397		cf := newCmdFlags("vote")
398		id := cf.fs.String("id", "", "proposal id to vote on")
399		voter := cf.fs.String("voter", "", "voting member (must be a final representative)")
400		choice := cf.fs.String("choice", "", "vote choice: for or against")
401		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64)")
402		cf.parse(args)
403		if *id == "" || *voter == "" {
404			fmt.Fprintf(os.Stderr, "usage error: --id and --voter are required\n")
405			os.Exit(2)
406		}
407		var support bool
408		switch *choice {
409		case "for":
410			support = true
411		case "against":
412			support = false
413		default:
414			fmt.Fprintf(os.Stderr, "usage error: --choice must be %q or %q\n", "for", "against")
415			os.Exit(2)
416		}
417		now := parseIntFlag(cf.fs, "now", *nowRaw)
418	
419		store, err := govflow.Open(cf.state)
420		if err != nil {
421			fail(err)
422		}
423		defer store.Close()
424		ballot, err := store.CastVote(*id, *voter, support, now)
425		if err != nil {
426			fail(err)
427		}
428		if cf.asJSON {
429			emitJSON(ballot)
430			return
431		}
432		fmt.Printf("recorded vote proposal=%s representative=%s choice=%s weight=%d voted_at=%d\n",
433			*id, ballot.Representative, choiceWord(ballot.Support), ballot.Weight, ballot.VotedAt)
434	}
435	
436	func choiceWord(support bool) string {
437		if support {
438			return "for"
439		}
440		return "against"
441	}
442	
443	func runTally(args []string) {
444		cf := newCmdFlags("tally")
445		id := cf.fs.String("id", "", "proposal id to tally")
446		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64, >= deadline)")
447		cf.parse(args)
448		if *id == "" {
449			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
450			os.Exit(2)
451		}
452		now := parseIntFlag(cf.fs, "now", *nowRaw)
453	
454		store, err := govflow.Open(cf.state)
455		if err != nil {
456			fail(err)
457		}
458		defer store.Close()
459		result, err := store.TallyVote(*id, now)
460		if err != nil {
461			fail(err)
462		}
463		if cf.asJSON {
464			emitJSON(map[string]any{"id": *id, "result": result})
465			return
466		}
467		verdict := "rejected"
468		if result.Passed {
469			verdict = "passed"
470		}
471		fmt.Printf("tally proposal=%s for=%d against=%d turnout=%d quorum=%d => %s (tallied_at=%d)\n",
472			*id, result.ForWeight, result.AgainstWeight, result.Turnout, result.Quorum, verdict, result.TalliedAt)
473	}
474	
475	func runExecute(args []string) {
476		cf := newCmdFlags("execute")
477		id := cf.fs.String("id", "", "proposal id to execute")
478		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64)")
479		cf.parse(args)
480		if *id == "" {
481			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
482			os.Exit(2)
483		}
484		now := parseIntFlag(cf.fs, "now", *nowRaw)
485	
486		store, err := govflow.Open(cf.state)
487		if err != nil {
488			fail(err)
489		}
490		defer store.Close()
491		receipt, err := store.Execute(*id, now)
492		if err != nil {
493			var derr *govflow.DurabilityError
494			if receipt != nil && errors.As(err, &derr) {
495				// 状态文件已替换成功：转账、executed 状态与凭据已写入，只是
496				// 目录同步失败、持久性未确认。标准输出照常给出已写入的凭据，
497				// 标准错误说明告警（提案编号 + 具体失败原因），退出码仍为 1。
498				if cf.asJSON {
499					emitJSON(receipt)
500				} else {
501					printReceiptText(receipt, false)
502				}
503				fmt.Fprintf(os.Stderr, "warning: proposal %s: execution record written but durability not confirmed: %v\n", *id, derr.Cause)
504				os.Exit(1)
505			}
506			fail(err)
507		}
508		if cf.asJSON {
509			emitJSON(receipt)
510			return
511		}
512		printReceiptText(receipt, false)
513	}
514	
515	func runBalances(args []string) {
516		cf := newCmdFlags("balances")
517		account := cf.fs.String("account", "", "show only this recipient account balance (unknown accounts are 0)")
518		cf.parse(args)
519		store, err := govflow.Open(cf.state)
520		if err != nil {
521			fail(err)
522		}
523		defer store.Close()
524		// 一次快照读取保证资金库与账户余额来自同一份已提交状态，
525		// 不会把并发执行前后的数字拼在一起。
526		snapshot, err := store.BalanceSnapshot()
527		if err != nil {
528			fail(err)
529		}
530		if *account != "" {
531			// 未出现过的账户余额为 0，且不向状态文件新增账户记录。
532			balance := snapshot.Balances[*account]
533			if cf.asJSON {
534				emitJSON(map[string]any{"treasury": snapshot.Treasury, "account": *account, "balance": balance})
535			} else {
536				fmt.Printf("treasury %d\n%s %d\n", snapshot.Treasury, *account, balance)
537			}
538			return
539		}
540		if cf.asJSON {
541			emitJSON(map[string]any{"treasury": snapshot.Treasury, "balances": snapshot.Balances})
542			return
543		}
544		fmt.Printf("treasury %d\n", snapshot.Treasury)
545		accounts := make([]string, 0, len(snapshot.Balances))
546		for acct := range snapshot.Balances {
547			accounts = append(accounts, acct)
548		}
549		sort.Strings(accounts)
550		for _, acct := range accounts {
551			fmt.Printf("%s %d\n", acct, snapshot.Balances[acct])
552		}
553	}
554	
555	func runProposal(args []string) {
556		cf := newCmdFlags("proposal")
557		id := cf.fs.String("id", "", "proposal id")
558		cf.parse(args)
559		if *id == "" {
560			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
561			os.Exit(2)
562		}
563		store, err := govflow.Open(cf.state)
564		if err != nil {
565			fail(err)
566		}
567		defer store.Close()
568		record, ok, err := store.Proposal(*id)
569		if err != nil {
570			fail(err)
571		}
572		if ok {
573			// 保持既有 JSON 形状：直接输出登记提案记录。
574			if cf.asJSON {
575				emitJSON(record)
576				return
577			}
578			printProposalText(record)
579			return
580		}
581		voteView, vok, verr := store.VoteProposal(*id)
582		if verr != nil {
583			fail(verr)
584		}
585		if !vok {
586			fail(fmt.Errorf("%w: %s", govflow.ErrProposalNotFound, *id))
587		}
588		if cf.asJSON {
589			emitJSON(voteView)
590			return
591		}
592		printVoteProposalText(voteView)
593	}
594	
595	func runProposals(args []string) {
596		cf := newCmdFlags("proposals")
597		cf.parse(args)
598		store, err := govflow.Open(cf.state)
599		if err != nil {
600			fail(err)
601		}
602		defer store.Close()
603		// 一次快照读取保证登记提案与投票提案来自同一份已提交状态，
604		// 不会把并发执行前后的提案状态拼在一起。
605		snapshot, err := store.ProposalsSnapshot()
606		if err != nil {
607			fail(err)
608		}
609		registered := snapshot.Registered
610		voting := snapshot.Voting
611		if cf.asJSON {
612			// 保持既有 JSON 形状：一个数组；登记记录字段不变，投票提案带额外字段。
613			merged := make([]any, 0, len(registered)+len(voting))
614			for _, r := range registered {
615				merged = append(merged, r)
616			}
617			for _, v := range voting {
618				merged = append(merged, v)
619			}
620			emitJSON(merged)
621			return
622		}
623		for _, record := range registered {
624			printProposalText(record)
625		}
626		for _, view := range voting {
627			printVoteProposalText(view)
628		}
629	}
630	
631	func runReceipt(args []string) {
632		cf := newCmdFlags("receipt")
633		id := cf.fs.String("id", "", "proposal id")
634		cf.parse(args)
635		if *id == "" {
636			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
637			os.Exit(2)
638		}
639		store, err := govflow.Open(cf.state)
640		if err != nil {
641			fail(err)
642		}
643		defer store.Close()
644		receipt, ok, err := store.Receipt(*id)
645		if err != nil {
646			fail(err)
647		}
648		if !ok {
649			fail(fmt.Errorf("no execution receipt for proposal %s", *id))
650		}
651		if cf.asJSON {
652			emitJSON(receipt)
653			return
654		}
655		printReceiptText(receipt, true)
656	}
657	
658	func runReceipts(args []string) {
659		cf := newCmdFlags("receipts")
660		cf.parse(args)
661		store, err := govflow.Open(cf.state)
662		if err != nil {
663			fail(err)
664		}
665		defer store.Close()
666		receipts, err := store.Receipts()
667		if err != nil {
668			fail(err)
669		}
670		if cf.asJSON {
671			emitJSON(receipts)
672			return
673		}
674		for _, receipt := range receipts {
675			printReceiptText(receipt, true)
676		}
677	}
678	
679	func printProposalText(p govflow.ProposalRecord) {
680		fmt.Printf("proposal %s state=%s timelock_end=%d actions=%d\n", p.ID, p.State, p.TimelockEnd, len(p.Actions))
681		for i, action := range p.Actions {
682			fmt.Printf("  action %d: %s\n", i, action)
683		}
684	}
685	
686	func printVoteProposalText(v *govflow.VoteProposalView) {
687		fmt.Printf("proposal %s source=vote state=%s quorum=%d voting=[%d,%d) timelock_end=%d actions=%d total_weight=%d\n",
688			v.ID, v.State, v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd, len(v.Actions), v.TotalWeight)
689		for _, m := range v.Members {
690			chain := strings.Join(m.Path, "->")
691			if len(m.Path) == 1 {
692				fmt.Printf("  member %s weight=%d representative=self\n", m.ID, m.Weight)
693			} else {
694				fmt.Printf("  member %s weight=%d path=%s\n", m.ID, m.Weight, chain)
695			}
696		}
697		for i, action := range v.Actions {
698			fmt.Printf("  action %d: %s\n", i, action)
699		}
700		for _, b := range v.Ballots {
701			fmt.Printf("  ballot representative=%s choice=%s weight=%d voted_at=%d\n",
702				b.Representative, choiceWord(b.Support), b.Weight, b.VotedAt)
703		}
704		if v.Tally != nil {
705			verdict := "rejected"
706			if v.Tally.Passed {
707				verdict = "passed"
708			}
709			fmt.Printf("  tally for=%d against=%d turnout=%d => %s tallied_at=%d\n",
710				v.Tally.ForWeight, v.Tally.AgainstWeight, v.Tally.Turnout, verdict, v.Tally.TalliedAt)
711		}
712	}
713	
714	func printReceiptText(r *govflow.Receipt, header bool) {
715		if header {
716			fmt.Printf("receipt proposal=%s order=%d executed_at=%d actions=%d\n", r.ProposalID, r.Order, r.ExecutedAt, len(r.Actions))
717		} else {
718			fmt.Printf("executed proposal %s at %d (%d action(s)); receipt order %d\n", r.ProposalID, r.ExecutedAt, len(r.Actions), r.Order)
719		}
720		for _, ar := range r.Actions {
721			fmt.Printf("  action %d: %s\n", ar.Index, ar.Action)
722			fmt.Printf("    treasury:  %d -> %d\n", ar.Treasury.Before, ar.Treasury.After)
723			fmt.Printf("    %s: %d -> %d\n", ar.Recipient.Account, ar.Recipient.Before, ar.Recipient.After)
724		}
725	}
